void CTRL_checkUserInput_run()
{
    RC_t result = RC_SUCCESS;
    
    //Set Ticktime upon first call
    if (0 == CTRL__timerTickTime)
    {
        CTRL__timerTickTime = RTE_getTickTime(RTE_cyclicActivationTable, RTE_cyclicActivation_size, CTRL_checkUserInput_run);
    }
    
    //Event signal
    EVENT_data_t ev = EVENT_INIT_DATA;
    
    //Get Button states
    
    //Brake
    result = RTE_BUTTON_pullPort(&SO_BRAKEBUTTON_signal);
    BUTTON_data_t brake = RTE_BUTTON_get(&SO_BRAKEBUTTON_signal);
    
    if (BUTTON_PRESSED == brake.m_button) 
    {
        ev.m_ev = EVENT_brakePressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }
    
    if (BUTTON_DEPRESSED == brake.m_button) 
    {
        ev.m_ev = EVENT_brakeDepressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }    
    
    //Ignition
    result = RTE_BUTTON_pullPort(&SO_IGNITIONBUTTON_signal);
    BUTTON_data_t ignition = RTE_BUTTON_get(&SO_IGNITIONBUTTON_signal);
    
    if (BUTTON_PRESSED == ignition.m_button) 
    {
        ev.m_ev = EVENT_ignitionPressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }
    
    if (BUTTON_DEPRESSED == ignition.m_button) 
    {
        ev.m_ev = EVENT_ignitionDepressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }    

    //LOG_I("CTRL_checkUserInput_run","B1 = %x",SO_DIRECTIONBUTTON_signal.value.m_button);
    //Direction
    result = RTE_BUTTON_pullPort(&SO_DIRECTIONBUTTON_signal);
    BUTTON_data_t direction = RTE_BUTTON_get(&SO_DIRECTIONBUTTON_signal);
    
    if (BUTTON_PRESSED == direction.m_button) 
    {
        ev.m_ev = EVENT_directionPressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }
    
    if (BUTTON_DEPRESSED == direction.m_button) 
    {
        ev.m_ev = EVENT_directionDepressed;
        RTE_EVENT_set(&SO_EVENT_signal, ev);
    }    
    
    
    //And don't forget to fire a tick event in every cycle
    ev.m_ev = EVENT_tick;
    RTE_EVENT_set(&SO_EVENT_signal, ev);

}

void CTRL_state_run()
{
    //Get event and state
    EVENT_data_t ev = RTE_EVENT_get(&SO_EVENT_signal);
    CARSTATE_data_t carstate = RTE_CARSTATE_get(&SO_CARSTATE_signal);

    //Just for debugging
    CAR_state_t fromState = carstate.m_state;

    
    switch (carstate.m_state)
    {
    case ISIDLE: 
        if (EVENT_ignitionPressed == ev.m_ev)
        {
            CTRL__startTimer(1000);
            carstate.m_state = ISPRESSEDIGNITION;
        }
        break;
    
    case ISPRESSEDIGNITION:
        if (EVENT_tick == ev.m_ev)
        {
            if (TRUE == CTRL__timerReachedZero())
            {
                //Ignition was pressed for one second
                CTRL__setLed(LED_1, LED_ON);
                CTRL__startTimer(10000);
                carstate.m_state = ISIGNITIONSELFTEST_1;
            }
            else
            {
                CTRL__decrementTimer(CTRL__timerTickTime);
            }
        }
        else if (EVENT_ignitionDepressed == ev.m_ev)
        {
            //Ignition was depressed before timeout
            CTRL__engineStop(&carstate);
            carstate.m_state = ISIDLE;
        }
        
        break;
        
    case ISIGNITIONSELFTEST_1:
        if (EVENT_tick == ev.m_ev)
        {
            if (TRUE == CTRL__timerReachedZero())
            {
                //Brake was not pressed in time
                CTRL__setLed(LED_ALL, LED_OFF);
                carstate.m_state = ISIDLE;
            }
            else
            {
                CTRL__decrementTimer(CTRL__timerTickTime);
            }
        }
        else if (EVENT_brakePressed == ev.m_ev)
        {
            //Brake was pressed
            carstate.m_state = ISIGNITIONSELFTEST_2;
        }
        
        break;
        
    case ISIGNITIONSELFTEST_2:
        if (EVENT_tick == ev.m_ev)
        {
            if (TRUE == CTRL__timerReachedZero())
            {
                //Brake was not depressed in time
                CTRL__setLed(LED_ALL, LED_OFF);
                carstate.m_state = ISIDLE;
            }
            else
            {
                CTRL__decrementTimer(CTRL__timerTickTime);
            }
        }
        else if (EVENT_brakeDepressed == ev.m_ev)
        {
            //Brake was depressed
            CTRL__setLed(LED_2, LED_ON);
            carstate.m_state = ISDRIVING;
        }
        break;
    
    case ISDRIVING:
        if (EVENT_tick == ev.m_ev)
        {
            //Normal driving
            CTRL__setTargetSpeed(&carstate);
        }
        else if (EVENT_directionPressed == ev.m_ev)
        {
            if (TRUE == CTRL__engineIsStopped())
            {
                //Toggle driving direction
                CTRL__toggleDirection(&carstate);
            }
        }
        else if (EVENT_brakePressed == ev.m_ev)
        {
            CTRL__setLed(LED_3, LED_ON);
            carstate.m_state = ISBRAKING;
        }
        else if (EVENT_error == ev.m_ev)
        {
            //Error has occured
            CTRL__engineStop(&carstate);
            CTRL__setLed(LED_3, LED_ON);
            carstate.m_state = ISERROR;
        }
        else if (EVENT_ignitionPressed == ev.m_ev)
        {
            CTRL__engineStop(&carstate);
            CTRL__setLed(LED_ALL, LED_OFF);
            carstate.m_state = ISIDLE;
        }
            
        break;
        
    case ISBRAKING:
        if (EVENT_tick == ev.m_ev)
        {
            CTRL__reduceTargetSpeed();
        }
        else if (EVENT_brakeDepressed == ev.m_ev)
        {
            CTRL__setLed(LED_3, LED_OFF);
            carstate.m_state = ISDRIVING;
        }
        else if (EVENT_error == ev.m_ev)
        {
            //Error has occured
            CTRL__engineStop(&carstate);
            CTRL__setLed(LED_3, LED_ON);
            carstate.m_state = ISERROR;
        }
        else if (EVENT_ignitionPressed == ev.m_ev)
        {
            CTRL__engineStop(&carstate);
            CTRL__setLed(LED_ALL, LED_OFF);
            carstate.m_state = ISIDLE;
        }
            
        break;
    
    case ISERROR:
        if (EVENT_brakePressed == ev.m_ev)
        {
            CTRL__engineStop(&carstate);
            CTRL__setLed(LED_ALL, LED_OFF);
            carstate.m_state = ISIDLE;
        }
        break;
        
    }   
        
    if (ev.m_ev != EVENT_tick) LOG_I("CTRL_state_run","ev = %d fromstate = %d tostate = %d",ev.m_ev, fromState, carstate.m_state);
    
    //Write carstate back to RTE
    RTE_CARSTATE_set(&SO_CARSTATE_signal, carstate);
    

}


