static void CTRL__engineStop(CARSTATE_data_t *const cardata)
{
    RC_t result = RC_SUCCESS;
    
    cardata->m_maxSpeed = 0;
    cardata->m_direction = DIRECTION_NEUTRAL;
     
    SPEED_data_t targetSpeed = SPEED_INIT_DATA;
    targetSpeed.m_rpm = 0;
        
     SSD1306_write_line(1,"Engine Stopped");
     SSD1306_write_line(2,"");
    
    //Set the targetspeed and write to RTE
    result = RTE_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);
    
}

