static void CTRL__setTargetSpeed(CARSTATE_data_t *const cardata)
{
    RC_t result = RC_SUCCESS;
    
    //Read in all required signals and check the status
    PEDAL_data_t pedal = RTE_PEDAL_get(&SO_PEDALPOSITION_signal);
    RTE_signalStatus_t pedalStatus = RTE_PEDAL_getStatus(&SO_PEDALPOSITION_signal);
    
    
    if (RTE_SIGNALSTATUS_VALID != pedalStatus) 
    {
        //In case pedal is invalid, automatically the last old value will used. 
        //Better: explizit check of pedal validity and don'T chenge the target signal
        
        return;
    }
    
    SPEED_data_t targetSpeed = SPEED_INIT_DATA;

    
    //Calculate targetspeed based on pedal position
    targetSpeed.m_rpm = (pedal.m_value * ENG_MAXRPM) / 100;
    
    if (DIRECTION_REVERSE == cardata->m_direction)
    {
        targetSpeed.m_rpm = -targetSpeed.m_rpm;
        
        //Limit speed - attention, negative values
        if (targetSpeed.m_rpm < ENG_MAXREVERSERPM)
        {
            targetSpeed.m_rpm = ENG_MAXREVERSERPM;
        }
    }
    else if (DIRECTION_NEUTRAL == cardata->m_direction)
    {
        targetSpeed.m_rpm = 0;
    }
    //Forward: nothing needs to be done;
    
    
    //Set the targetspeed and write to RTE
    result = RTE_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);
   
}

static void CTRL__reduceTargetSpeed()
{
    RC_t result = RC_SUCCESS;
    
    SPEED_data_t targetSpeed = RTE_SPEED_get(&SO_TARGETSPEED_signal);
    
    if (targetSpeed.m_rpm < 0) targetSpeed.m_rpm++ ;
    else if (targetSpeed.m_rpm > 0) targetSpeed.m_rpm-- ;
    
    //Set the targetspeed and write to RTE
    result = RTE_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);
    
}

static void CTRL__toggleDirection(CARSTATE_data_t *const cardata)
{
    switch (cardata->m_direction)
    {
        case DIRECTION_NEUTRAL:
            cardata->m_direction = DIRECTION_FORWARD;
            SSD1306_write_line(1,"Direction");
            SSD1306_write_line(2,"  - Forward");
        break;
        case DIRECTION_FORWARD:
            cardata->m_direction = DIRECTION_REVERSE;
            SSD1306_write_line(1,"Direction");
            SSD1306_write_line(2,"  - Reverse");
        break;
        case DIRECTION_REVERSE:
            cardata->m_direction = DIRECTION_NEUTRAL;
            SSD1306_write_line(1,"Direction");
            SSD1306_write_line(2,"  - Neutral");
        break;
    }
}

static void CTRL__setLed(LED_id_t led, LED_mode_t mode)
{
    LED_data_t led_s = RTE_LED_get(&SO_LED_signal);
    
    switch (led){
        case LED_1 : 
            led_s.m_led_1 = mode; 
        break;
        case LED_2 : 
            led_s.m_led_2 = mode; 
        break;
        case LED_3 : 
            led_s.m_led_3 = mode; 
        break;
        case LED_4 : 
            led_s.m_led_4 = mode; 
        break;
        case LED_ALL :
            led_s.m_led_1 = mode;
            led_s.m_led_2 = mode;
            led_s.m_led_3 = mode;
            led_s.m_led_4 = mode;
        break;
    }
    
    RTE_LED_set(&SO_LED_signal, led_s);
    RTE_LED_pushPort(&SO_LED_signal);
    
}



